  "Octopus":        {type:"Familiar",size:"Tiny",ac:"12",hp:"3",speed:"5ft / swim 30ft",str:4,dex:15,con:11,int:3,wis:10,cha:4,attacks:[{name:"Tentacles",atk:"+4",dmg:"1 bludg (grapple DC 10)"},{name:"Ink Cloud",atk:"--",dmg:"recharge 6 (blind 5ft radius)"}],notes:"Underwater Camouflage: adv Stealth underwater<br>Hold Breath 30 min"},
  "Owl":            {type:"Familiar",size:"Tiny",ac:"11",hp:"1",speed:"5ft / fly 60ft",str:3,dex:13,con:8,int:2,wis:12,cha:7,attacks:[{name:"Talons",atk:"+3",dmg:"1 slash"}],skills:[{name:"Perception",bonus:3},{name:"Stealth",bonus:3}],notes:"Flyby: no opportunity attacks<br>Keen Hearing+Sight<br>Darkvision 120ft"},
