  "Rat":            {type:"Familiar",size:"Tiny",ac:"10",hp:"1",speed:"20ft",str:2,dex:11,con:9,int:2,wis:10,cha:4,attacks:[{name:"Bite",atk:"+0",dmg:"1 pierc"}],notes:"Keen Smell"},
