function charLoad() {
 try {
 const raw = localStorage.getItem(CHAR_KEY);
 if (raw) {
 const saved = JSON.parse(raw);
      // Merge with BLANK so new fields added in updates are always present
 return { ...BLANK, ...saved,
 abilities: { ...BLANK.abilities, ...(saved.abilities||{}) },
 hp: { ...BLANK.hp, ...(saved.hp||{}) },
 deathSaves: { ...BLANK.deathSaves, ...(saved.deathSaves||{}) },
 currency: { ...BLANK.currency, ...(saved.currency||{}) },
 partyCurrency: { ...BLANK.partyCurrency, ...(saved.partyCurrency||{}) },
 treasureItems: Array.isArray(saved.treasureItems) ? saved.treasureItems : [],
 resistances: Array.isArray(saved.resistances)      ? saved.resistances      : [],
 immunities: Array.isArray(saved.immunities)       ? saved.immunities       : [],
 vulnerabilities: Array.isArray(saved.vulnerabilities)  ? saved.vulnerabilities  : [],
 weapons: Array.isArray(saved.weapons)          ? saved.weapons          : BLANK.weapons,
 attackSpells: Array.isArray(saved.attackSpells)     ? saved.attackSpells     : BLANK.attackSpells,
 spellSlotsUsed: Array.isArray(saved.spellSlotsUsed)   ? saved.spellSlotsUsed   : BLANK.spellSlotsUsed,
 spellsKnown: Array.isArray(saved.spellsKnown)      ? saved.spellsKnown      : [],
 preparedSpells: Array.isArray(saved.preparedSpells)   ? saved.preparedSpells   : [],
 photos: Array.isArray(saved.photos) && saved.photos.length ? saved.photos : (()=>{try{const p=localStorage.getItem(CHAR_KEY+"_photos");return p?JSON.parse(p):[];}catch(_){return[];}})(),
 cards: Array.isArray(saved.cards) && saved.cards.length ? saved.cards : (()=>{try{const p=localStorage.getItem(CHAR_KEY+"_cards");return p?JSON.parse(p):[];}catch(_){return[];}})(),
 documents: Array.isArray(saved.documents) && saved.documents.length ? saved.documents : (()=>{try{const p=localStorage.getItem(CHAR_KEY+"_docs");return p?JSON.parse(p):[];}catch(_){return[];}})(),
 conditions: Array.isArray(saved.conditions)       ? saved.conditions       : [],
 saveProficiencies: Array.isArray(saved.saveProficiencies)    ? saved.saveProficiencies    : [],
 skillProficiencies: Array.isArray(saved.skillProficiencies)   ? saved.skillProficiencies   : [],
 skillExpertise: Array.isArray(saved.skillExpertise)       ? saved.skillExpertise       : [],
 classSkills: Array.isArray(saved.classSkills)         ? saved.classSkills         : [],
 languages: Array.isArray(saved.languages)           ? saved.languages            : [],
 sessions: Array.isArray(saved.sessions)            ? saved.sessions             : [],
        // Migration: clear multiClass if multiClassLevel is 0 (not actually multiclassed)
 multiClass: (saved.multiClassLevel > 0) ? (saved.multiClass || "") : "",
        // Migration: fix companionSpeed if it was mangled by old regex (e.g. "1560" from "15 / fly 60")
        // A purely numeric value over 999 is a concatenation artifact — keep as-is if it looks like a formatted string
 companionSpeed: (()=>{
          const s=String(saved.companionSpeed||"");
          if(!s) return s;
          // If it's a plain number over 999, extract first digit group (old bug)
          if(/^\d+$/.test(s)&&Number(s)>999) return (s.match(/\d+/)||[""])[0]+"ft";
          // Ensure ft appears after every bare number
          return s.replace(/(\d+)\s*(ft)?/gi,(_,n)=>n+"ft");
        })(),
        // Migration: clean stale companionNotes that still contain old flat-sentence format with Skills/boilerplate
 companionNotes: (()=>{
          const n=saved.companionNotes||"";
          // Only migrate plain-text notes (no existing <br> or HTML — those are already clean)
          if(!n||n.includes("<br>")||n.includes("<b>")||n.includes("<i>")) return n;
          // Strip boilerplate fields already shown in the UI
          let clean=n
            .replace(/Type:[^.]+\.\s*/gi,"")
            .replace(/Size:[^.]+\.\s*/gi,"")
            .replace(/AC:[^.]+\.\s*/gi,"")
            .replace(/HP:[^.]+\.\s*/gi,"")
            .replace(/Speed:[^.]+\.\s*/gi,"")
            .replace(/STR\s+\d+\s+DEX\s+\d+\s+CON\s+\d+\s+INT\s+\d+\s+WIS\s+\d+\s+CHA\s+\d+\.\s*/gi,"")
            .replace(/Skills?:[^.]+\.\s*/gi,"")
            .replace(/Acts?:[^.]+(\([^)]+\)[^.]*)*\.\s*/gi,"")
            .replace(/Traits?:\s*/gi,"")
            .trim().replace(/\.\s*$/,"");
          // Convert remaining ". " sentence breaks into <br> lines
          const parts=clean.split(/\.\s+/).map(s=>s.trim()).filter(Boolean);
          return parts.join("<br>");
        })(),
        // Migration: fix stale companionAttacks that still have old compound damage strings
        // e.g. dmg:"1d4+3 pierc + CON DC 11 or 3d6 poison" -> dmg:"1d4+3 Piercing", atk2:"CON DC 11 or", dmg2:"3d6 poison"
 companionAttacks: (Array.isArray(saved.companionAttacks)?saved.companionAttacks:[]).map(a=>{
          if(!a) return a;
          let dmg=a.dmg||"";
          let atk2=a.atk2||"";
          let dmg2=a.dmg2||"";
          // Only migrate if dmg has a compound pattern and atk2/dmg2 are not yet split
          if(!atk2&&!dmg2&&/\+\s*CON\s+DC|or\s+\d+d\d+/i.test(dmg)){
            const saveMatch=dmg.match(/\s*\+?\s*(CON\s+DC\s+\d+\s+or)\s+(.+)$/i);
            if(saveMatch){
              dmg=dmg.slice(0,dmg.length-(saveMatch[0].length)).trim();
              atk2=saveMatch[1].trim();
              dmg2=saveMatch[2].trim();
            }
          }
          // Fix atk2 that is missing the DC number (e.g. "CON DC or" written without the number)
          // Look up the correct value from COMPANION_DATA using the companion type and attack name
          if(atk2&&/^CON\s+DC\s+or$/i.test(atk2.trim())){
            const compData=COMPANION_DATA[saved.companionType]||null;
            if(compData&&Array.isArray(compData.attacks)){
              const match=compData.attacks.find(ca=>ca.name===a.name&&ca.atk2);
              if(match) atk2=match.atk2;
            }
          }
          // Clear stale atk2/dmg2 if COMPANION_DATA says this attack has no secondary effect
          if(atk2||dmg2){
            const compData=COMPANION_DATA[saved.companionType]||null;
            if(compData&&Array.isArray(compData.attacks)){
              const match=compData.attacks.find(ca=>ca.name===a.name);
              if(match&&!match.atk2&&!match.dmg2){ atk2=""; dmg2=""; }
            }
          }
          // Expand abbreviated damage type words
          dmg=dmg.replace(/\bpierc\b/i,"Piercing").replace(/\bslash\b/i,"Slashing").replace(/\bbludg\b/i,"Bludgeoning");
          return {...a,dmg,atk2,dmg2};
        }),
      };
    }
  } catch(_) {}
 return BLANK;
}

function charSave(c) {
 try {
    localStorage.setItem(CHAR_KEY, JSON.stringify(c));
  } catch(e) {
    // If quota exceeded, try saving without the media arrays first, then save media separately
    try {
      const {photos,cards,documents,...rest}=c;
      localStorage.setItem(CHAR_KEY, JSON.stringify(rest));
      try { if(photos&&photos.length) localStorage.setItem(CHAR_KEY+"_photos", JSON.stringify(photos)); } catch(_){}
      try { if(cards&&cards.length) localStorage.setItem(CHAR_KEY+"_cards", JSON.stringify(cards)); } catch(_){}
      try { if(documents&&documents.length) localStorage.setItem(CHAR_KEY+"_docs", JSON.stringify(documents)); } catch(_){}
    } catch(_) {}
  }
}

const CONDITIONS = ["Blinded","Charmed","Deafened","Exhaustion","Frightened","Grappled","Incapacitated","Invisible","Paralyzed","Petrified","Poisoned","Prone","Restrained","Stunned","Unconscious"];

// MULTICLASS RULES (enforced on sheet, not stored in library)
// Prereqs: [ability, minScore] - all must be met
const MC_PREREQS = {
  Barbarian: [["STR",13]],
  Bard: [["CHA",13]],
  Cleric: [["WIS",13]],
  Druid: [["WIS",13]],
  Fighter: [["STR",13]], // OR DEX 13 - handled as union below
  Monk: [["DEX",13],["WIS",13]],
  Paladin: [["STR",13],["CHA",13]],
  Ranger: [["DEX",13],["WIS",13]],
  Rogue: [["DEX",13]],
  Sorcerer: [["CHA",13]],
  Warlock: [["CHA",13]],
  Wizard: [["INT",13]],
};
// Fighter/Ranger have OR conditions - we handle them separately
const MC_PREREQS_OR = {
  Fighter: [["STR",13],["DEX",13]], // need STR 13 OR DEX 13
  Ranger: null, // Ranger needs both DEX+WIS (covered above)
};

function mcPrereqMet(className, abilities) {
 if (MC_PREREQS_OR[className]) {
    // OR logic: at least one must be met
 return MC_PREREQS_OR[className].some(([ab,score]) => (abilities[ab]||10) >= score);
  }
 const prereqs = MC_PREREQS[className];
 if (!prereqs) return true;
 return prereqs.every(([ab,score]) => (abilities[ab]||10) >= score);
}

function mcFailedPrereqs(className, abilities) {
 if (MC_PREREQS_OR[className]) {
 const orPrereqs = MC_PREREQS_OR[className];
 const anyMet = orPrereqs.some(([ab,score]) => (abilities[ab]||10) >= score);
 return anyMet ? [] : orPrereqs; // show all OR options if none met
  }
 return (MC_PREREQS[className]||[]).filter(([ab,score]) => (abilities[ab]||10) < score);
}

