 setSkillRoll({label:"Breath Weapon ("+dmgDice+")",roll:total,bonus:0,total,isCrit:false,isFail:false,sides:die,r1:rolls[0],r2:null,allRolls:[...rolls],isAdv:false,isDis:false});
