                    const castLabels={"1 action":"Action","1 bonus action":"Bonus Action","1 reaction":"Reaction","1 minute":"1 Minute","10 minutes":"10 Minutes","1 hour":"1 Hour","8 hours":"8 Hours","1 round":"1 Round"};
                    const ranges=["","Self","Touch","ranged","Special","Sight","Unlimited"];
